def _file_sha256(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def _fraction(value: sp.Rational | int) -> str:
    rational = sp.Rational(value)
    return str(rational.p) if rational.q == 1 else f"{rational.p}/{rational.q}"


def _matrix(payload: Sequence[Sequence[str | int]]) -> sp.Matrix:
    return sp.Matrix([[sp.Rational(value) for value in row] for row in payload])


def _matrix_payload(matrix: sp.Matrix) -> list[list[str]]:
    return [[_fraction(value) for value in matrix.row(index)] for index in range(matrix.rows)]


def _vector_payload(vector: sp.Matrix) -> list[str]:
    return [_fraction(value) for value in vector]


def _content(vector: Iterable[sp.Rational | int]) -> int:
    values = [abs(int(value)) for value in vector if value]
    return reduce(math.gcd, values)


def _primitive(vector: sp.Matrix) -> sp.Matrix:
    values = [sp.Rational(value) for value in vector]
    denominator = int(sp.ilcm(*(value.q for value in values)))
    integral = sp.Matrix([int(value * denominator) for value in values])
    return integral / _content(integral)


def _unoriented_key(vector: sp.Matrix) -> tuple[int, ...]:
    primitive = tuple(int(value) for value in _primitive(vector))
    first = next(value for value in primitive if value)
    return primitive if first > 0 else tuple(-value for value in primitive)


def _pair(gram: sp.Matrix, left: sp.Matrix, right: sp.Matrix) -> sp.Rational:
    return sp.Rational((left.T * gram * right)[0])


def _reflection(gram: sp.Matrix, root: sp.Matrix) -> sp.Matrix:
    square = _pair(gram, root, root)
    reflection = sp.simplify(
        sp.eye(gram.rows) - sp.Rational(2, square) * root * (root.T * gram)
    )
    if not (
        all(value.is_Integer for value in reflection)
        and int(reflection.det()) == -1
        and reflection.T * gram * reflection == gram
        and reflection * reflection == sp.eye(gram.rows)
    ):
        raise ArithmeticError("a claimed doubling reflection is not an integral involution")
    return reflection


def _ratio(gram: sp.Matrix, left: sp.Matrix, right: sp.Matrix) -> sp.Rational:
    return sp.factor(
        _pair(gram, left, right) ** 2
        / (_pair(gram, left, left) * _pair(gram, right, right))
    )


def _relation_token(ratio: sp.Rational) -> str:
    finite = {
        sp.Rational(0): "2",
        sp.Rational(1, 4): "3",
        sp.Rational(1, 2): "4",
        sp.Rational(3, 4): "6",
        sp.Rational(1): "parallel",
    }
    if ratio in finite:
        return finite[ratio]
    if ratio > 1:
        return f"dotted:{_fraction(ratio)}"
    raise ArithmeticError(f"non-Coxeter normalized product {ratio}")


def _relations(
    gram: sp.Matrix, roots: Sequence[sp.Matrix]
) -> tuple[tuple[str, ...], ...]:
    if any(
        _pair(gram, roots[left], roots[right]) < 0
        for left in range(len(roots))
        for right in range(left)
    ):
        raise ArithmeticError("a doubled chamber is not acute-angled")
    return tuple(
        tuple(
            "1" if left == right else _relation_token(_ratio(gram, alpha, beta))
            for right, beta in enumerate(roots)
        )
        for left, alpha in enumerate(roots)
    )


def _doubling_walls(relations: Sequence[Sequence[str]]) -> list[int]:
    odd = {"3", "5", "7", "9"}
    return [
        index
        for index, row in enumerate(relations)
        if all(token not in odd for token in row)
    ]


def _relation_graph(relations: Sequence[Sequence[str]]) -> nx.Graph:
    graph = nx.Graph()
    graph.add_nodes_from(range(len(relations)))
    for left in range(len(relations)):
        for right in range(left):
            token = relations[left][right]
            if token != "2":
                graph.add_edge(left, right, relation=token)
    return graph


EDGE_MATCH = nx.algorithms.isomorphism.categorical_edge_match("relation", None)


def _isomorphic(
    left: Sequence[Sequence[str]], right: Sequence[Sequence[str]]
) -> bool:
    return nx.is_isomorphic(
        _relation_graph(left), _relation_graph(right), edge_match=EDGE_MATCH
    )


def _load_seed(
    factory: dict[str, Any], seed_type: str
) -> tuple[
    dict[str, Any],
    sp.Matrix,
    tuple[sp.Matrix, ...],
    sp.Matrix,
    tuple[sp.Matrix, ...],
]:
    config = SEEDS[seed_type]
    source = next(
        row for row in factory["constructions"] if row["id"] == config["source_id"]
    )
    section = source["section"]
    gram = _matrix(section["saturated_fixed_lattice"]["gram"])
    active_records = tuple(
        record
        for record in section["restricted_mirrors"]["records"]
        if record["hyperbolic_status"] == "active_facet"
    )
    roots = tuple(
        sp.Matrix(record["primitive_integral_same_direction_coordinates"])
        for record in active_records
    )
    interior = sp.Matrix(
        [
            sp.Rational(value)
            for value in section["strict_fixed_interior"]["fixed_lattice_coordinates"]
        ]
    )
    roots = tuple(
        -root if _pair(gram, interior, root) < 0 else root for root in roots
    )
    witness_by_orbit = {
        int(record["orbit_index"]): sp.Matrix(
            [sp.Rational(value) for value in record["fixed_lattice_coordinates"]]
        )
        for record in section["exact_reduction"]["strict_facet_witnesses"]
    }
    witnesses = tuple(
        witness_by_orbit[int(record["orbit_index"])] for record in active_records
    )
    if not (
        gram.shape == (10, 10)
        and exact_inertia(gram) == (1, 9, 0)
        and len(roots) == 14
        and all(_pair(gram, interior, root) > 0 for root in roots)
        and all(
            _pair(gram, witnesses[target], roots[target]) == 0
            and _pair(gram, witnesses[target], witnesses[target]) > 0
            and all(
                _pair(gram, witnesses[target], roots[index]) > 0
                for index in range(len(roots))
                if index != target
            )
            for target in range(len(roots))
        )
    ):
        raise ArithmeticError(f"seed {seed_type} failed exact lattice replay")
    relations = _relations(gram, roots)
    doubling = _doubling_walls(relations)
    expected = [index - 1 for index in config["doubling_walls_one_based"]]
    if doubling != expected or any(
        _pair(gram, roots[left], roots[right]) != 0
        for position, left in enumerate(doubling)
        for right in doubling[position + 1 :]
    ):
        raise ArithmeticError(f"seed {seed_type} doubling-wall stock changed")
    return section, gram, roots, interior, witnesses


def _doubling_cube(
    gram: sp.Matrix,
    seed_roots: Sequence[sp.Matrix],
    seed_interior: sp.Matrix,
    seed_witnesses: Sequence[sp.Matrix],
    selected: Sequence[int],
) -> dict[str, Any]:
    generators = tuple(_reflection(gram, seed_roots[index]) for index in selected)
    if any(
        left * right != right * left
        for position, left in enumerate(generators)
        for right in generators[position + 1 :]
    ):
        raise ArithmeticError("orthogonal doubling reflections do not commute")
    transforms = []
    for mask in range(1 << len(generators)):
        transform = sp.eye(gram.rows)
        for index, generator in enumerate(generators):
            if mask & (1 << index):
                transform = generator * transform
        transforms.append(transform)
    if len({tuple(transform) for transform in transforms}) != 1 << len(generators):
        raise ArithmeticError("the doubling reflection cube is not elementary abelian")

    boundary: dict[tuple[int, ...], tuple[sp.Matrix, sp.Matrix]] = {}
    selected_set = set(selected)
    for transform in transforms:
        for index, seed_root in enumerate(seed_roots):
            if index in selected_set:
                continue
            root = _primitive(transform * seed_root)
            boundary.setdefault(
                _unoriented_key(root),
                (root, transform * seed_witnesses[index]),
            )
    interior = sum(
        (transform * seed_interior for transform in transforms),
        sp.zeros(gram.rows, 1),
    )
    roots = []
    witnesses = []
    for key in sorted(boundary):
        root, witness = boundary[key]
        pairing = _pair(gram, interior, root)
        if pairing == 0:
            raise ArithmeticError("a doubled boundary wall contains the cube interior")
        roots.append(-root if pairing < 0 else root)
        witnesses.append(witness)
    roots_tuple = tuple(roots)
    if not (
        _pair(gram, interior, interior) > 0
        and all(_pair(gram, interior, root) > 0 for root in roots_tuple)
        and sp.Matrix.hstack(*roots_tuple).rank() == gram.rows
    ):
        raise ArithmeticError("the doubled chamber is not full-dimensional and oriented")
    if not all(
        _pair(gram, witnesses[target], roots_tuple[target]) == 0
        and _pair(gram, witnesses[target], witnesses[target]) > 0
        and all(
            _pair(gram, witnesses[target], roots_tuple[index]) > 0
            for index in range(len(roots_tuple))
            if index != target
        )
        for target in range(len(roots_tuple))
    ):
        raise ArithmeticError("a doubled boundary inequality lacks a strict facet witness")
    reflections = tuple(_reflection(gram, root) for root in roots_tuple)
    relations = _relations(gram, roots_tuple)
    return {
        "roots": roots_tuple,
        "interior": interior,
        "relations": relations,
        "strict_facet_witnesses": tuple(witnesses),
        "reflection_count": len(reflections),
        "copy_count": len(transforms),
        "subgroup_order": len(transforms),
    }


def _relation_histogram(relations: Sequence[Sequence[str]]) -> dict[str, int]:
    return {
        token: count
        for token, count in sorted(
            Counter(
                relations[left][right]
                for left in range(len(relations))
                for right in range(left)
            ).items()
        )
    }


def _cone(
    gram: sp.Matrix, roots: Sequence[sp.Matrix], interior: sp.Matrix
) -> dict[str, Any]:
    inequality = sp.Matrix.vstack(*(root.T * gram for root in roots))
    slacks = inequality * interior
    if not (
        inequality.rank() == gram.rows
        and all(value > 0 for value in slacks)
    ):
        raise ArithmeticError("doubled homogeneous cone failed rank/orientation")
    lines = [
        "H-representation",
        "begin",
        f"{len(roots)} {gram.rows + 1} rational",
    ]
    lines.extend(
        "0 " + " ".join(_fraction(value) for value in inequality.row(index))
        for index in range(inequality.rows)
    )
    lines.append("end")
    return {
        "fixed_gram": gram,
        "inequality": inequality,
        "active_orbit_indices": tuple(range(1, len(roots) + 1)),
        "dimension": gram.rows - 1,
        "rank": gram.rows,
        "inequality_text": "\n".join(lines) + "\n",
        "minimum_strict_slack": min(slacks),
    }


def _case_payload(
    identifier: str,
    section: dict[str, Any],
    gram: sp.Matrix,
    roots: Sequence[sp.Matrix],
    interior: sp.Matrix,
) -> dict[str, Any]:
    facet_gram = sp.Matrix(
        [[_pair(gram, left, right) for right in roots] for left in roots]
    )
    return {
        "id": identifier,
        "ambient_key": section["ambient_key"],
        "saturated_fixed_lattice": section["saturated_fixed_lattice"],
        "strict_fixed_interior": {
            "fixed_lattice_coordinates": _vector_payload(interior),
        },
        "restricted_mirrors": {
            "facet_gram": _matrix_payload(facet_gram),
        },
    }


def _classify_all_subsets(
    gram: sp.Matrix,
    roots: Sequence[sp.Matrix],
    interior: sp.Matrix,
    witnesses: Sequence[sp.Matrix],
    doubling_walls: Sequence[int],
) -> tuple[dict[str, Any], dict[tuple[int, ...], dict[str, Any]]]:
    census: dict[str, Any] = {}
    constructions: dict[tuple[int, ...], dict[str, Any]] = {}
    for size in range(1, len(doubling_walls) + 1):
        classes: list[dict[str, Any]] = []
        for selected in combinations(doubling_walls, size):
            construction = _doubling_cube(
                gram, roots, interior, witnesses, selected
            )
            constructions[selected] = construction
            match = next(
                (
                    record
                    for record in classes
                    if _isomorphic(
                        construction["relations"], record["representative_relations"]
                    )
                ),
                None,
            )
            if match is None:
                classes.append(
                    {
                        "representative_selected_walls_one_based": [
                            index + 1 for index in selected
                        ],
                        "representative_relations": construction["relations"],
                        "selected_subsets_one_based": [
                            [index + 1 for index in selected]
                        ],
                        "facet_count": len(construction["roots"]),
                        "relation_histogram": _relation_histogram(
                            construction["relations"]
                        ),
                        "doubling_wall_count": len(
                            _doubling_walls(construction["relations"])
                        ),
                    }
                )
            else:
                match["selected_subsets_one_based"].append(
                    [index + 1 for index in selected]
                )
        census[str(1 << size)] = {
            "selected_wall_count": size,
            "subset_count": math.comb(len(doubling_walls), size),
            "isomorphism_type_count": len(classes),
            "types": [
                {key: value for key, value in record.items() if key != "representative_relations"}
                for record in classes
            ],
        }
    return census, constructions


def _corpus_relations(matrix: Sequence[Sequence[str]]) -> tuple[tuple[str, ...], ...]:
    replacements = {"0": "parallel", "infinity": "parallel", "∞": "parallel"}
    return tuple(
        tuple(replacements.get(str(value), str(value)) for value in row)
        for row in matrix
    )


def _pinned_coxiter_lineage(
    candidates: Sequence[tuple[tuple[str, ...], ...]],
) -> dict[str, Any]:
    """Exclude literal matches in the pinned ordinary and doubling corpora."""

    if not (
        _file_sha256(COXITER_ARCHIVE) == COXITER_ARCHIVE_SHA256
        and _file_sha256(DOUBLING_ARCHIVE) == DOUBLING_ARCHIVE_SHA256
    ):
        raise ArithmeticError("the pinned CoxIter lineage archives changed")
    records: list[dict[str, Any]] = []
    with zipfile.ZipFile(COXITER_ARCHIVE) as archive:
        ordinary_members = sorted(
            name for name in archive.namelist() if name.endswith(".coxiter")
        )
        for name in ordinary_members:
            facets, dimension, matrix = _parse_coxiter_text(
                archive.read(name).decode("utf-8", errors="replace")
            )
            if dimension == 9 and 15 <= facets <= 18:
                records.append(
                    {
                        "lane": "ordinary",
                        "path": name,
                        "facets": facets,
                        "relations": _corpus_relations(matrix),
                    }
                )
    doubling_file_count = 0
    with tarfile.open(DOUBLING_ARCHIVE, "r:gz") as archive:
        for member in archive:
            if not member.isfile() or not member.name.endswith(".coxiter"):
                continue
            doubling_file_count += 1
            handle = archive.extractfile(member)
            if handle is None:
                raise ArithmeticError(f"cannot read {member.name}")
            facets, dimension, matrix = _parse_coxiter_text(
                handle.read().decode("utf-8", errors="replace")
            )
            if dimension == 9 and 15 <= facets <= 18:
                records.append(
                    {
                        "lane": "doubling",
                        "path": member.name,
                        "facets": facets,
                        "relations": _corpus_relations(matrix),
                    }
                )
    header_histogram = Counter(record["facets"] for record in records)
    if not (
        len(ordinary_members) == 1214
        and doubling_file_count == 2959
        and dict(sorted(header_histogram.items())) == {15: 8}
    ):
        raise ArithmeticError("the pinned H9/15--18 corpus inventory changed")

    comparisons = []
    exact_matches = []
    histogram_collisions = []
    for candidate_index, candidate in enumerate(candidates, start=1):
        same_header = [
            record for record in records if record["facets"] == len(candidate)
        ]
        candidate_histogram = _relation_histogram(candidate)
        matches = [
            record["path"]
            for record in same_header
            if _isomorphic(candidate, record["relations"])
        ]
        collisions = [
            record["path"]
            for record in same_header
            if _relation_histogram(record["relations"]) == candidate_histogram
            and not _isomorphic(candidate, record["relations"])
        ]
        exact_matches.extend(matches)
        histogram_collisions.extend(collisions)
        comparisons.append(
            {
                "candidate_index": candidate_index,
                "facet_count": len(candidate),
                "same_header_record_count": len(same_header),
                "relation_histogram_collision_count": len(collisions),
                "exact_labelled_graph_match_count": len(matches),
            }
        )
    if exact_matches or histogram_collisions:
        raise ArithmeticError("a doubling-cube diagram collides with pinned CoxIter")
    return {
        "scope": "bounded corpus exclusion, not a worldwide priority theorem",
        "coxiter_commit": COXITER_COMMIT,
        "ordinary_archive_sha256": COXITER_ARCHIVE_SHA256,
        "doubling_archive_sha256": DOUBLING_ARCHIVE_SHA256,
        "ordinary_file_count": len(ordinary_members),
        "doubling_file_count": doubling_file_count,
        "H9_facet_15_through_18_header_histogram": {
            str(key): value for key, value in sorted(header_histogram.items())
        },
        "candidate_comparisons": comparisons,
        "total_exact_labelled_graph_match_count": 0,
        "total_relation_histogram_collision_count": 0,
    }


def build(executable: str | None = None) -> tuple[dict[str, Any], dict[Path, bytes]]:
    if _file_sha256(SOURCE) != SOURCE_SHA256:
        raise ArithmeticError("the H9/14 seed factory changed")
    factory = json.loads(SOURCE.read_text(encoding="utf-8"))
    cdd = executable or shutil.which("cddexec_gmp") or "cddexec_gmp"
    artifacts: dict[Path, bytes] = {}
    seed_payloads: dict[str, Any] = {}
    certified_types: list[dict[str, Any]] = []
    global_relations: list[tuple[tuple[str, ...], ...]] = []

    for seed_type, config in SEEDS.items():
        section, gram, seed_roots, seed_interior, seed_witnesses = _load_seed(
            factory, seed_type
        )
        doubling_walls = [index - 1 for index in config["doubling_walls_one_based"]]
        census, constructions = _classify_all_subsets(
            gram, seed_roots, seed_interior, seed_witnesses, doubling_walls
        )
        actual_type_counts = {
            copies: record["isomorphism_type_count"] for copies, record in census.items()
        }
        if actual_type_counts != config["expected_type_count_by_copy_count"]:
            raise ArithmeticError(f"{seed_type} doubling-cube type census changed")

        representative_records = []
        for representative_one_based in config["representatives_one_based"]:
            selected = tuple(index - 1 for index in representative_one_based)
            construction = constructions[selected]
            copies = int(construction["copy_count"])
            suffix = "_".join(map(str, representative_one_based))
            identifier = f"{seed_type}_D{copies}_W{suffix}"
            roots = construction["roots"]
            interior = construction["interior"]
            relations = construction["relations"]
            if any(_isomorphic(relations, prior) for prior in global_relations):
                raise ArithmeticError("two selected cube representatives are isomorphic")
            global_relations.append(relations)
            cone = _cone(gram, roots, interior)
            cdd_output = _run_cdd(cone["inequality_text"], cdd)
            rays = _parse_cdd_rays(cdd_output, gram.rows)
            case = _case_payload(identifier, section, gram, roots, interior)
            volume, ray_archive = _analyze_case(case, cone, rays)
            time_orientation = _time_orientation(case, cone, rays)
            vinberg = _literal_vinberg(case, cone, rays)
            exact = volume["exact_double_description"]
            if not (
                volume["decision"]["classification"] == "finite_volume_noncompact"
                and exact["hyperideal_vertex_count"] == 0
                and exact["ideal_vertex_count"] > 0
                and time_orientation["all_extreme_rays_same_time_cone"] is True
                and vinberg["literal_vinberg_passes"] is True
                and vinberg["bad_edge_count"] == 0
                and vinberg["bad_parabolic_neighborhood_count"] == 0
            ):
                raise ArithmeticError(f"{identifier} failed the exact volume gate")
            inequality_path = INEQUALITY_DIRECTORY / f"{identifier}.ine"
            ray_path = RAY_DIRECTORY / f"{identifier}.jsonl.gz"
            inequality_bytes = cone["inequality_text"].encode()
            artifacts[inequality_path] = inequality_bytes
            artifacts[ray_path] = ray_archive
            record = {
                "id": identifier,
                "seed_type": seed_type,
                "selected_doubling_walls_one_based": representative_one_based,
                "copy_count": copies,
                "reflection_subgroup_order": construction["subgroup_order"],
                "hyperbolic_dimension": 9,
                "facet_count": len(roots),
                "strict_timelike_facet_witness_count": len(
                    construction["strict_facet_witnesses"]
                ),
                "roots_in_fixed_lattice_coordinates": [
                    _vector_payload(root) for root in roots
                ],
                "facet_gram": case["restricted_mirrors"]["facet_gram"],
                "relation_histogram": _relation_histogram(relations),
                "doubling_walls_one_based": [
                    index + 1 for index in _doubling_walls(relations)
                ],
                "exact_cone": volume,
                "time_orientation": time_orientation,
                "literal_vinberg": vinberg,
                "volume_multiple_of_seed": copies,
                "weak_full_picard_k3_carrier_inherited": True,
                "artifacts": {
                    "inequality_path": str(inequality_path.relative_to(ROOT)),
                    "inequality_sha256": sha256(inequality_bytes).hexdigest(),
                    "ray_archive_path": str(ray_path.relative_to(ROOT)),
                    "ray_archive_sha256": sha256(ray_archive).hexdigest(),
                },
            }
            representative_records.append(record)
            certified_types.append(record)

        seed_payloads[seed_type] = {
            "source_id": config["source_id"],
            "doubling_walls_one_based": config["doubling_walls_one_based"],
            "doubling_walls_mutually_orthogonal": True,
            "complete_nonempty_subset_count": 15,
            "isomorphism_census_by_copy_count": census,
            "certified_representatives": representative_records,
        }

    if len(certified_types) != 9:
        raise ArithmeticError("the two doubling cubes no longer have nine new types")
    lineage = _pinned_coxiter_lineage(global_relations)
    payload = {
        "schema": SCHEMA,
        "source": {
            "factory_path": str(SOURCE.relative_to(ROOT)),
            "factory_sha256": SOURCE_SHA256,
        },
        "scope": {
            "abstract_hyperbolic_coxeter_polytopes_certified": True,
            "finite_volume_and_noncompactness_certified": True,
            "integral_fixed_lattice_reflections_certified": True,
            "weak_full_picard_k3_divisor_carriers_certified": True,
            "nef_or_surface_automorphism_claimed": False,
            "worldwide_novelty_claimed": False,
        },
        "theorem": {
            "seed_count": 2,
            "nonempty_doubling_subset_count_per_seed": 15,
            "new_project_ledger_isomorphism_type_count": 9,
            "facet_count_range": [15, 18],
            "copy_count_range": [2, 16],
            "all_types_finite_volume_noncompact": True,
            "all_types_pairwise_nonisomorphic": True,
        },
        "seeds": seed_payloads,
        "certified_types": certified_types,
        "bounded_lineage_audit": lineage,
        "decision": {
            "classification": "nine_pairwise_nonisomorphic_finite_volume_noncompact_H9_doubling_cube_polytopes",
            "worldwide_priority_status": (
                "absent_from_pinned_CoxIter_corpora_worldwide_priority_open"
            ),
        },
    }
    return payload, artifacts


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check-archive", action="store_true")
    parser.add_argument("--cdd", default=None)
    args = parser.parse_args()
    payload, artifacts = build(args.cdd)
    rendered = (json.dumps(payload, indent=2, sort_keys=True) + "\n").encode()
    if args.check_archive:
        if OUTPUT.read_bytes() != rendered:
            raise ArithmeticError("doubling-cube JSON archive changed")
        for path, content in artifacts.items():
            if path.read_bytes() != content:
                raise ArithmeticError(f"doubling-cube artifact changed: {path}")
    else:
        OUTPUT.parent.mkdir(parents=True, exist_ok=True)
        OUTPUT.write_bytes(rendered)
        for path, content in artifacts.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)
    print(json.dumps(payload["theorem"], sort_keys=True))
    print(OUTPUT)


if __name__ == "__main__":
    main()
